// Viewport — Gtk.Viewport
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles viewport with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface ViewportProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Widget, from Gtk.Viewport */
  child?: ReactNode

  /** gboolean, from Gtk.Viewport */
  scrollToFocus?: boolean
}

export function Viewport({ className, children }: ViewportProps) {
  return (
    <div className={cn("rounded-tl-[18px]", "rounded-tr-[18px]", className)}>
      {children}
    </div>
  )
}
